// A Chart of the Isle of Unfortunate Timing — a treasure map drawn by code.
//
// The program draws one 1024x1024 treasure map of a fictional whale-shaped
// island where everything is slightly unlucky, and writes it to
// $MAKEFUN_OUTPUT_DIR/entry.png (or /output/entry.png). Pure Node, no
// dependencies, no network, no clock: a seeded PRNG is the only source of
// variation, so two runs produce byte-identical output.
//
// How the picture is built: every shape is a vector path (polygons, bezier
// curves, circles) rasterised into a 2x supersampled RGB buffer, text is set
// from real DejaVu Serif glyph outlines embedded below, and the buffer is
// written out as a PNG by a small hand-rolled encoder.

import { mkdirSync, writeFileSync } from "node:fs";
import { deflateSync } from "node:zlib";

// ------------------------------------------------------------------ constants

const W = 1024;
const H = 1024;
const SS = 2; // supersampling factor
const CW = W * SS;
const CH = H * SS;

// Palette: aged parchment, pale teal sea, sandy island, dark brown ink.
const PAPER: RGB = [233, 216, 165];
const PAPER_DARK: RGB = [214, 192, 138];
const CARTOUCHE: RGB = [240, 226, 184];
const SEA: RGB = [168, 197, 186];
const SEA_DEEP: RGB = [140, 176, 164];
const WAVE: RGB = [110, 150, 138];
const SAND: RGB = [226, 205, 148];
const LAND: RGB = [228, 210, 156];
const GREEN_WASH: RGB = [178, 192, 132];
const FOREST: RGB = [95, 127, 69];
const HILL: RGB = [203, 178, 121];
const RIVER: RGB = [143, 195, 217];
const RIVER_BANK: RGB = [93, 139, 166];
const INK: RGB = [74, 52, 33];
const INK_SOFT: RGB = [107, 79, 48];
const RED: RGB = [176, 58, 42];
const RED_DARK: RGB = [143, 45, 32];
const TEAL_TEXT: RGB = [47, 107, 107];
const WHITE: RGB = [250, 244, 224];

type RGB = [number, number, number];

// ------------------------------------------------------------- seeded random

function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const R = mulberry32(1743);

// ------------------------------------------------------------------- canvas

const buf = new Uint8Array(CW * CH * 3);
for (let i = 0; i < CW * CH; i++) {
  buf[i * 3] = PAPER[0];
  buf[i * 3 + 1] = PAPER[1];
  buf[i * 3 + 2] = PAPER[2];
}

function setPx(sx: number, sy: number, c: RGB, a: number): void {
  if (sx < 0 || sy < 0 || sx >= CW || sy >= CH) return;
  const i = (sy * CW + sx) * 3;
  const inv = 1 - a;
  buf[i] = Math.round(buf[i] * inv + c[0] * a);
  buf[i + 1] = Math.round(buf[i + 1] * inv + c[1] * a);
  buf[i + 2] = Math.round(buf[i + 2] * inv + c[2] * a);
}

// Fill a disc in supersampled coords.
function disc(cx: number, cy: number, r: number, c: RGB, a: number): void {
  const x0 = Math.max(0, Math.floor(cx - r));
  const x1 = Math.min(CW - 1, Math.ceil(cx + r));
  const y0 = Math.max(0, Math.floor(cy - r));
  const y1 = Math.min(CH - 1, Math.ceil(cy + r));
  for (let y = y0; y <= y1; y++) {
    for (let x = x0; x <= x1; x++) {
      const dx = x + 0.5 - cx;
      const dy = y + 0.5 - cy;
      if (dx * dx + dy * dy <= r * r) setPx(x, y, c, a);
    }
  }
}

type Pt = [number, number]; // logical (1024-space) coordinates

function s(p: Pt): Pt {
  return [p[0] * SS, p[1] * SS];
}

// Even-odd scanline fill of a polygon given as logical points.
function fillPoly(pts: Pt[], c: RGB, a: number): void {
  if (pts.length < 3) return;
  const sp = pts.map(s);
  let minY = Infinity;
  let maxY = -Infinity;
  for (const [, y] of sp) {
    if (y < minY) minY = y;
    if (y > maxY) maxY = y;
  }
  const y0 = Math.max(0, Math.floor(minY));
  const y1 = Math.min(CH - 1, Math.ceil(maxY));
  for (let y = y0; y <= y1; y++) {
    const yc = y + 0.5;
    const xs: number[] = [];
    for (let i = 0; i < sp.length; i++) {
      const [x1, y1p] = sp[i];
      const [x2, y2p] = sp[(i + 1) % sp.length];
      if ((y1p <= yc && y2p > yc) || (y2p <= yc && y1p > yc)) {
        xs.push(x1 + ((yc - y1p) / (y2p - y1p)) * (x2 - x1));
      }
    }
    xs.sort((p, q) => p - q);
    for (let k = 0; k + 1 < xs.length; k += 2) {
      const xa = Math.max(0, Math.ceil(xs[k]));
      const xb = Math.min(CW - 1, Math.floor(xs[k + 1]));
      for (let x = xa; x <= xb; x++) setPx(x, y, c, a);
    }
  }
}

// Fill a path made of several contours (even-odd across contours): each
// contour is a list of points; used for glyph outlines with holes.
function fillContours(contours: Pt[][], c: RGB, a: number): void {
  if (contours.length === 0) return;
  const sc = contours.map((ct) => ct.map(s));
  let minY = Infinity;
  let maxY = -Infinity;
  for (const ct of sc)
    for (const [, y] of ct) {
      if (y < minY) minY = y;
      if (y > maxY) maxY = y;
    }
  const y0 = Math.max(0, Math.floor(minY));
  const y1 = Math.min(CH - 1, Math.ceil(maxY));
  for (let y = y0; y <= y1; y++) {
    const yc = y + 0.5;
    const xs: number[] = [];
    for (const ct of sc) {
      for (let i = 0; i < ct.length; i++) {
        const [x1, y1p] = ct[i];
        const [x2, y2p] = ct[(i + 1) % ct.length];
        if ((y1p <= yc && y2p > yc) || (y2p <= yc && y1p > yc)) {
          xs.push(x1 + ((yc - y1p) / (y2p - y1p)) * (x2 - x1));
        }
      }
    }
    xs.sort((p, q) => p - q);
    for (let k = 0; k + 1 < xs.length; k += 2) {
      const xa = Math.max(0, Math.ceil(xs[k]));
      const xb = Math.min(CW - 1, Math.floor(xs[k + 1]));
      for (let x = xa; x <= xb; x++) setPx(x, y, c, a);
    }
  }
}

// Thick polyline: stamps discs along each segment, so joints are round.
function strokePoly(
  pts: Pt[],
  width: number,
  c: RGB,
  a: number,
  dash?: [number, number],
): void {
  const r = (width * SS) / 2;
  const step = Math.max(0.6, r * 0.5);
  for (let i = 0; i + 1 < pts.length; i++) {
    const [x1, y1] = s(pts[i]);
    const [x2, y2] = s(pts[i + 1]);
    const len = Math.hypot(x2 - x1, y2 - y1);
    if (len === 0) continue;
    const n = Math.max(1, Math.ceil(len / step));
    if (!dash) {
      for (let k = 0; k <= n; k++) {
        disc(x1 + ((x2 - x1) * k) / n, y1 + ((y2 - y1) * k) / n, r, c, a);
      }
    } else {
      // Dashes measured along the segment, in logical units.
      const [dLen, gap] = dash;
      let d = 0;
      const total = len / SS;
      while (d < total) {
        const a0 = d;
        const b0 = Math.min(d + dLen, total);
        const t0 = a0 / total;
        const t1 = b0 / total;
        const m = Math.max(1, Math.ceil(((b0 - a0) * SS) / step));
        for (let k = 0; k <= m; k++) {
          const t = t0 + ((t1 - t0) * k) / m;
          disc(x1 + (x2 - x1) * t, y1 + (y2 - y1) * t, r, c, a);
        }
        d = b0 + gap;
      }
    }
  }
}

function strokeRect(x: number, y: number, w: number, h: number, width: number, c: RGB, a: number): void {
  strokePoly(
    [
      [x, y],
      [x + w, y],
      [x + w, y + h],
      [x, y + h],
      [x, y],
    ],
    width,
    c,
    a,
  );
}

function fillRect(x: number, y: number, w: number, h: number, c: RGB, a: number): void {
  fillPoly(
    [
      [x, y],
      [x + w, y],
      [x + w, y + h],
      [x, y + h],
    ],
    c,
    a,
  );
}

function fillEllipse(cx: number, cy: number, rx: number, ry: number, c: RGB, a: number): void {
  const pts: Pt[] = [];
  const n = 48;
  for (let i = 0; i < n; i++) {
    const t = (i / n) * Math.PI * 2;
    pts.push([cx + Math.cos(t) * rx, cy + Math.sin(t) * ry]);
  }
  fillPoly(pts, c, a);
}

function ellipseOutline(cx: number, cy: number, rx: number, ry: number, width: number, c: RGB, a: number): void {
  const pts: Pt[] = [];
  const n = 64;
  for (let i = 0; i <= n; i++) {
    const t = (i / n) * Math.PI * 2;
    pts.push([cx + Math.cos(t) * rx, cy + Math.sin(t) * ry]);
  }
  strokePoly(pts, width, c, a);
}

// Cubic bezier flattened to a polyline (fixed subdivision, plenty at our sizes).
function cubicPts(p0: Pt, p1: Pt, p2: Pt, p3: Pt, steps = 16): Pt[] {
  const out: Pt[] = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    out.push([
      mt * mt * mt * p0[0] + 3 * mt * mt * t * p1[0] + 3 * mt * t * t * p2[0] + t * t * t * p3[0],
      mt * mt * mt * p0[1] + 3 * mt * mt * t * p1[1] + 3 * mt * t * t * p2[1] + t * t * t * p3[1],
    ]);
  }
  return out;
}

function quadPts(p0: Pt, p1: Pt, p2: Pt, steps = 12): Pt[] {
  const out: Pt[] = [];
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const mt = 1 - t;
    out.push([
      mt * mt * p0[0] + 2 * mt * t * p1[0] + t * t * p2[0],
      mt * mt * p0[1] + 2 * mt * t * p1[1] + t * t * p2[1],
    ]);
  }
  return out;
}

// Catmull-Rom spline through points, returned as a flattened polyline.
function catmullRom(pts: Pt[], closed: boolean, stepsPerSeg = 14): Pt[] {
  const P = closed ? [...pts, pts[0], pts[1], pts[2]] : [pts[0], ...pts, pts[pts.length - 1]];
  const out: Pt[] = [];
  const n = closed ? pts.length : pts.length - 1;
  for (let i = 0; i < n; i++) {
    const p0 = P[i];
    const p1 = P[i + 1];
    const p2 = P[i + 2];
    const p3 = P[i + 3];
    for (let k = 0; k < stepsPerSeg; k++) {
      const t = k / stepsPerSeg;
      const t2 = t * t;
      const t3 = t2 * t;
      out.push([
        0.5 * (2 * p1[0] + (-p0[0] + p2[0]) * t + (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * t2 + (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * t3),
        0.5 * (2 * p1[1] + (-p0[1] + p2[1]) * t + (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * t2 + (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * t3),
      ]);
    }
  }
  return out;
}

