function main(): void {
  drawPaper();
  drawSea();
  drawIsland();
  drawInterior();
  drawRoute();
  drawFurniture();
  drawLabels();
  const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "/output";
  mkdirSync(outDir, { recursive: true });
  const png = encodePng();
  writeFileSync(`${outDir}/entry.png`, png);
  console.log(`wrote ${outDir}/entry.png (${png.length} bytes)`);
}

main();
